import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Extracts — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"extracts-02-how-tos-and-workflows.md","filePath":"extracts-02-how-tos-and-workflows.md"}'),i={name:"extracts-02-how-tos-and-workflows.md"};function n(s,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="extracts-—-how-tos-workflows" tabindex="-1">Extracts — How-tos &amp; Workflows <a class="header-anchor" href="#extracts-—-how-tos-workflows" aria-label="Permalink to &quot;Extracts — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Extracts workflows</em></p><hr><h2 id="uploading-a-transcript-manually" tabindex="-1">Uploading a Transcript Manually <a class="header-anchor" href="#uploading-a-transcript-manually" aria-label="Permalink to &quot;Uploading a Transcript Manually&quot;">​</a></h2><p>The simplest way to get a transcript into Lodestone is to upload it directly.</p><ol><li>Navigate to the Extracts module from the left-hand navigation.</li><li>Select the option to upload a transcript.</li><li>Upload your transcript file.</li><li>Submit. Lodestone&#39;s AI will analyze the transcript and generate Extracts.</li></ol><p>A processing indicator is shown while analysis is in progress. Processing time varies depending on the length of the transcript. There is no notification when Extracts are ready — you&#39;ll need to return to the Extracts module and check manually.</p><blockquote><p><strong>Tip:</strong> For long transcripts, upload and come back a few minutes later rather than waiting on the page.</p></blockquote><hr><h2 id="importing-a-transcript-via-fireflies-or-gong" tabindex="-1">Importing a Transcript via Fireflies or Gong <a class="header-anchor" href="#importing-a-transcript-via-fireflies-or-gong" aria-label="Permalink to &quot;Importing a Transcript via Fireflies or Gong&quot;">​</a></h2><p>If your team uses Fireflies or Gong, you can import transcripts directly into the Extracts module without manual upload.</p><h3 id="importing-from-fireflies" tabindex="-1">Importing from Fireflies <a class="header-anchor" href="#importing-from-fireflies" aria-label="Permalink to &quot;Importing from Fireflies&quot;">​</a></h3><ol><li>Ensure the Fireflies integration is connected in Settings &gt; Integrations.</li><li>Navigate to the Extracts module.</li><li>Select the option to import from Fireflies.</li><li>Choose the meeting you want to analyze from your Fireflies library — any meeting in your Fireflies instance is accessible.</li><li>Confirm the import. Lodestone will pull the transcript and begin analysis.</li></ol><h3 id="importing-from-gong" tabindex="-1">Importing from Gong <a class="header-anchor" href="#importing-from-gong" aria-label="Permalink to &quot;Importing from Gong&quot;">​</a></h3><ol><li>Ensure the Gong integration is connected in Settings &gt; Integrations. During initial setup, you&#39;ll be prompted to select which Gong accounts to pull transcripts from — typically your front-line customer-facing colleagues such as AEs, CSMs, and SDRs.</li><li>Navigate to the Extracts module.</li><li>Select the option to import from Gong.</li><li>Choose the call you want to analyze from the available meetings.</li><li>Confirm the import. Lodestone will pull the transcript and begin analysis.</li></ol><blockquote><p><strong>Tip:</strong> When setting up the Gong integration, be deliberate about which accounts you select. Including too many accounts can surface a large volume of transcripts; focusing on your highest-signal roles (e.g. AEs running discovery calls) gives you more actionable Extracts.</p></blockquote><p>See the Integrations module guide for full setup instructions for both integrations.</p><hr><h2 id="filtering-and-searching-extracts" tabindex="-1">Filtering and Searching Extracts <a class="header-anchor" href="#filtering-and-searching-extracts" aria-label="Permalink to &quot;Filtering and Searching Extracts&quot;">​</a></h2><p>The Extracts module has a <strong>keyword filter</strong> and a <strong>live search</strong> bar to help you focus on what matters.</p><h3 id="keyword-filter" tabindex="-1">Keyword filter <a class="header-anchor" href="#keyword-filter" aria-label="Permalink to &quot;Keyword filter&quot;">​</a></h3><p>You can define a set of keywords that the AI uses as semantic emphasis during analysis — topics you care about most, like &quot;pricing&quot;, &quot;enterprise&quot;, or &quot;onboarding&quot;. Keywords are saved to your browser and persist across sessions. Add keywords before uploading a transcript to guide extraction, or use them to filter the results in your review queue.</p><p>To add a keyword: type it into the keyword input field and press Enter. To remove a keyword: click the × on any keyword chip.</p><h3 id="live-search" tabindex="-1">Live search <a class="header-anchor" href="#live-search" aria-label="Permalink to &quot;Live search&quot;">​</a></h3><p>The search bar filters your current Extract list in real time by Feature name, description, or quote text. Use it to find a specific idea or narrow a large batch of Extracts without scrolling through all of them.</p><hr><h2 id="reviewing-extracts" tabindex="-1">Reviewing Extracts <a class="header-anchor" href="#reviewing-extracts" aria-label="Permalink to &quot;Reviewing Extracts&quot;">​</a></h2><p>Once a transcript has been analyzed, the generated Extracts appear in your review queue. Each Extract shows a suggested Feature Name, Description, and any associated quotes pulled from the conversation. A <strong>source badge</strong> indicates where the Extract came from (Gong, Fireflies, Manual, or Intel Report).</p><p>Quotes may also display <strong>company name</strong>, <strong>speaker name</strong>, and <strong>revenue information</strong> when that data is available from the source. To remove an individual quote from an Extract, click the delete icon on the quote — deletion is permanent.</p><p>For each Extract, you have two options:</p><h3 id="add-to-backlog" tabindex="-1">Add to Backlog <a class="header-anchor" href="#add-to-backlog" aria-label="Permalink to &quot;Add to Backlog&quot;">​</a></h3><p>Promotes the Extract to a Backlog object. Clicking this option opens a confirmation dialog where you review each Extract before it is added.</p><p><strong>AI type suggestion:</strong> If your organization has configured object types in Settings &gt; Taxonomy, Lodestone&#39;s AI automatically suggests which type each Extract should become (e.g. Feature, Bug, Epic). The suggestion appears as &quot;✦ AI suggests: [type name]&quot; next to each Extract in the dialog. The suggested type is pre-selected in the type dropdown — you can accept it or choose a different type before confirming.</p><p><strong>AI goal match:</strong> If the Extract&#39;s content semantically matches an existing Goal in your Goals &amp; Objectives list, the dialog shows &quot;✦ AI matched parent goal: [Goal name]&quot; and pre-populates the goal selector. You can accept the match, choose a different goal, or leave it blank.</p><p>Both suggestions are optional and fully overridable. If no object types are configured, the type selection step does not appear.</p><p>The Extract is removed from the queue once added. The new Backlog object carries the Extract&#39;s name and description.</p><h3 id="dismiss" tabindex="-1">Dismiss <a class="header-anchor" href="#dismiss" aria-label="Permalink to &quot;Dismiss&quot;">​</a></h3><p>Permanently deletes the Extract. There is no undo — once dismissed, the Extract cannot be recovered. If an idea turns out to be important later, you&#39;ll need to create it manually as a Backlog item.</p><blockquote><p><strong>Tip:</strong> It&#39;s fine to work through Extracts in batches rather than reviewing them immediately after each upload. Strong PMs often look for patterns across a set of Extracts from multiple sessions before deciding what to act on.</p></blockquote><hr><h2 id="merging-duplicates" tabindex="-1">Merging Duplicates <a class="header-anchor" href="#merging-duplicates" aria-label="Permalink to &quot;Merging Duplicates&quot;">​</a></h2><p>The Extracts module automatically detects when two or more Extracts describe the same idea. When duplicates are found, a banner appears at the top of the extract list indicating how many duplicate groups were detected.</p><p>To resolve duplicates:</p><ol><li>Click the duplicate notification banner to open the merge dialog.</li><li>Review the group of similar Extracts.</li><li>Select a primary Extract (the one whose name and description you want to keep) or choose to enter custom values.</li><li>Click <strong>Merge</strong>. The selected Extracts are combined into one, and their associated quotes are consolidated.</li><li>If multiple duplicate groups exist, step through each one before closing the dialog.</li></ol><p>Merging is irreversible — the non-primary duplicates are removed after merging. Review each group carefully before confirming.</p><hr><h2 id="moving-a-quote-to-an-existing-backlog-feature" tabindex="-1">Moving a Quote to an Existing Backlog Feature <a class="header-anchor" href="#moving-a-quote-to-an-existing-backlog-feature" aria-label="Permalink to &quot;Moving a Quote to an Existing Backlog Feature&quot;">​</a></h2><p>Sometimes a quote surfaced in an Extract belongs to a Feature that already exists in your backlog, rather than representing a new idea. You can move a quote directly to an existing Feature without promoting the whole Extract.</p><ol><li>On an Extract card, find the quote you want to move.</li><li>Click the move icon on the quote.</li><li>Search for and select the existing backlog Feature you want to link the quote to.</li><li>Confirm. The quote is attached to the selected Feature&#39;s quote library.</li></ol><p>This is useful when a customer conversation reinforces evidence for something already on your roadmap rather than surfacing a net new idea.</p><hr><h2 id="editing-an-extract-before-promoting-it" tabindex="-1">Editing an Extract Before Promoting It <a class="header-anchor" href="#editing-an-extract-before-promoting-it" aria-label="Permalink to &quot;Editing an Extract Before Promoting It&quot;">​</a></h2><p>Extracts are not editable before promotion. The Feature Name and Description are generated by AI and carry over as-is when you add an Extract to the backlog. If you want to adjust the name or description, you can choose custom values when promoting — the promotion dialog allows you to override the suggested name and description before the Feature is created.</p><hr><h2 id="reviewing-extracts-in-bulk" tabindex="-1">Reviewing Extracts in Bulk <a class="header-anchor" href="#reviewing-extracts-in-bulk" aria-label="Permalink to &quot;Reviewing Extracts in Bulk&quot;">​</a></h2><p>Bulk actions are available when reviewing Extracts. You can select multiple Extracts at once and either add them all to the backlog or dismiss them all in one action. This is useful when reviewing a large batch of Extracts from a long transcript and want to quickly clear obvious noise or promote a cluster of related ideas.</p><hr><h2 id="finding-the-right-transcripts-to-upload" tabindex="-1">Finding the Right Transcripts to Upload <a class="header-anchor" href="#finding-the-right-transcripts-to-upload" aria-label="Permalink to &quot;Finding the Right Transcripts to Upload&quot;">​</a></h2><p>Extracts are most valuable when the source material is rich with customer signal. The best transcripts to run through the Extracts module are:</p><ul><li><strong>Customer interviews</strong> — direct feedback on problems, needs, and priorities</li><li><strong>Sales calls</strong> — prospect objections, feature requests, competitive mentions</li><li><strong>Support reviews</strong> — recurring issues, frustrations, and workarounds</li><li><strong>Stakeholder meetings</strong> — internal priorities, strategic input, and alignment discussions</li></ul><p>Internal planning meetings with no customer signal will produce fewer useful Extracts and more noise.</p><hr><p><em>Next: Advanced Features &amp; Customization — working with integrations, managing transcript sources, and getting the most from the AI.</em></p>',63)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
